  matriculaId: string;
  competencia: string;
  vencimento: string;
  valorCobranca: number;
  totalPago: number;
  saldoDevedor: number;
  situacao: string;
}

export const qryGetMensalidadeRoute = 'mensalidadesAcademia.pagamentosMensalidades.qryGetMensalidade' as const;

l4 entity: Mensalidade
l4 fields: Mensalidade.id, Mensalidade.matriculaId, Mensalidade.competencia, Mensalidade.vencimento, Mensalidade.details.valorCobranca, Mensalidade.details.totalPago, Mensalidade.details.saldoDevedor, Mensalidade.details.situacao
